# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
"""Triton implementation of aten::special_chebyshev_polynomial_t.

out = T_n(x):
  x < -1 : (-1)^n * cosh(n * acosh(-x))
  x >  1 : cosh(n * acosh(x))
  else   : cos(n * acos(x))          (includes x == -1 and x == 1)
"""

import logging

import torch
import triton
import triton.language as tl
from triton.language.extra import libdevice

logger = logging.getLogger(__name__)

_MAX_NDIM = 5
_MAX_POLY_DEGREE = 32
_MAX_INLINE_DEGREE = 8
_FLOAT_DTYPES = (torch.float32, torch.float64)
_BLOCK = 1024
_NUM_WARPS = 4

# Bounded fixed-source configuration search over launch geometry only.
_TUNE_CONFIGS = [
    triton.Config({"BLOCK": 256}, num_warps=1),
    triton.Config({"BLOCK": 256}, num_warps=2),
    triton.Config({"BLOCK": 512}, num_warps=2),
    triton.Config({"BLOCK": 512}, num_warps=4),
    triton.Config({"BLOCK": 1024}, num_warps=4),
    triton.Config({"BLOCK": 1024}, num_warps=8),
    triton.Config({"BLOCK": 2048}, num_warps=4),
    triton.Config({"BLOCK": 2048}, num_warps=8),
    triton.Config({"BLOCK": 4096}, num_warps=8),
    triton.Config({"BLOCK": 8192}, num_warps=8),
]


@triton.autotune(configs=_TUNE_CONFIGS, key=["numel"])
@triton.jit
def _cheb_flat_kernel(
    x_ptr,
    n_ptr,
    out_ptr,
    numel,
    n_scalar,
    N_MODE: tl.constexpr,  # 0: python scalar, 1: single element tensor, 2: elementwise tensor
    IS_FP64: tl.constexpr,
    BLOCK: tl.constexpr,
    MAXK: tl.constexpr,
):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < numel
    x = tl.load(x_ptr + offs, mask=mask, other=0.0)
    if IS_FP64:
        xv = x.to(tl.float64)
    else:
        xv = x.to(tl.float32)

    if N_MODE == 0:
        nv = (n_scalar * 1.0).to(xv.dtype)
        bad_degree = ((nv < 0.0) | (nv > MAXK) | (nv != tl.floor(nv))).to(tl.int32)
    elif N_MODE == 1:
        nv = tl.load(n_ptr).to(xv.dtype)
        bad_degree = ((nv < 0.0) | (nv > MAXK) | (nv != tl.floor(nv))).to(tl.int32)
    else:
        nv = tl.load(n_ptr + offs, mask=mask, other=0.0).to(xv.dtype)
        bad_degree = tl.max(
            ((nv < 0.0) | (nv > MAXK) | (nv != tl.floor(nv))).to(tl.int32), axis=0
        )

    # A degree that is an integer in [0, MAXK] on every lane needs no
    # transcendental at all: T_n(x) is the Chebyshev polynomial for every real
    # x, so one recurrence covers all three reference branches.
    if bad_degree == 0:
        out = tl.where(nv == 0.0, 1.0, xv)
        t_prev = tl.full([BLOCK], 1.0, xv.dtype)
        t_cur = xv
        for k in tl.static_range(2, MAXK + 1):
            t_next = 2.0 * xv * t_cur - t_prev
            out = tl.where(nv == k, t_next, out)
            t_prev = t_cur
            t_cur = t_next
    else:
        # tl.where cannot short-circuit, so an all-inside block would still pay
        # for the acosh/cosh pair.  Detect the uniform case and skip it.
        outside = tl.max(((xv < -1.0) | (xv > 1.0)).to(tl.int32), axis=0)
        if outside == 0:
            out = tl.cos(nv * libdevice.acos(xv))
        else:
            ax = tl.abs(xv)
            c = tl.cos(nv * libdevice.acos(xv))
            h = libdevice.cosh(nv * libdevice.acosh(ax))
            odd = (nv % 2.0) != 0.0
            sgn = tl.where(odd, -1.0, 1.0)
            out = tl.where(
                (xv >= -1.0) & (xv <= 1.0),
                c,
                tl.where(xv < 0.0, sgn * h, h),
            )
    tl.store(out_ptr + offs, out.to(out_ptr.dtype.element_ty), mask=mask)


@triton.autotune(configs=_TUNE_CONFIGS, key=["numel"])
@triton.jit
def _cheb_poly_kernel(
    x_ptr,
    out_ptr,
    numel,
    DEGREE: tl.constexpr,
    IS_FP64: tl.constexpr,
    BLOCK: tl.constexpr,
):
    """Exact Chebyshev polynomial for a non-negative integer degree.

    T_0 = 1, T_1 = x, T_k = 2x*T_{k-1} - T_{k-2}.  For integer degree this
    single polynomial equals cos(n*acos(x)) on [-1, 1] and
    cosh(n*acosh(|x|)) (with the (-1)^n sign for x < -1) outside, so the
    domain select and all transcendentals disappear.
    """
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < numel
    x = tl.load(x_ptr + offs, mask=mask, other=0.0)
    if IS_FP64:
        xv = x.to(tl.float64)
    else:
        xv = x.to(tl.float32)

    if DEGREE == 0:
        out = tl.full([BLOCK], 1.0, xv.dtype)
    else:
        t0 = tl.full([BLOCK], 1.0, xv.dtype)
        t1 = xv
        for _ in tl.static_range(2, DEGREE + 1):
            t2 = 2.0 * xv * t1 - t0
            t0 = t1
            t1 = t2
        out = t1
    tl.store(out_ptr + offs, out.to(out_ptr.dtype.element_ty), mask=mask)


@triton.jit
def _cheb_strided_kernel(
    x_ptr,
    n_ptr,
    out_ptr,
    numel,
    n_scalar,
    xs0,
    xs1,
    xs2,
    xs3,
    xs4,
    ns0,
    ns1,
    ns2,
    ns3,
    ns4,
    d1,
    d2,
    d3,
    d4,
    N_MODE: tl.constexpr,
    IS_FP64: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < numel

    rem = offs
    i4 = rem % d4
    rem = rem // d4
    i3 = rem % d3
    rem = rem // d3
    i2 = rem % d2
    rem = rem // d2
    i1 = rem % d1
    i0 = rem // d1

    xo = i0 * xs0 + i1 * xs1 + i2 * xs2 + i3 * xs3 + i4 * xs4
    x = tl.load(x_ptr + xo, mask=mask, other=0.0)
    if IS_FP64:
        xv = x.to(tl.float64)
    else:
        xv = x.to(tl.float32)

    if N_MODE == 0:
        nv = (n_scalar * 1.0).to(xv.dtype)
    elif N_MODE == 1:
        nv = tl.load(n_ptr).to(xv.dtype)
    else:
        no = i0 * ns0 + i1 * ns1 + i2 * ns2 + i3 * ns3 + i4 * ns4
        nv = tl.load(n_ptr + no, mask=mask, other=0.0).to(xv.dtype)

    ax = tl.abs(xv)
    c = tl.cos(nv * libdevice.acos(xv))
    h = libdevice.cosh(nv * libdevice.acosh(ax))
    odd = (nv % 2.0) != 0.0
    sgn = tl.where(odd, -1.0, 1.0)
    out = tl.where(
        (xv >= -1.0) & (xv <= 1.0),
        c,
        tl.where(xv < 0.0, sgn * h, h),
    )
    tl.store(out_ptr + offs, out.to(out_ptr.dtype.element_ty), mask=mask)


def special_chebyshev_polynomial_t(x, n):
    logger.debug("GEMS_THEAD SPECIAL_CHEBYSHEV_POLYNOMIAL_T")
    is_tensor_n = isinstance(n, torch.Tensor)
    if is_tensor_n:
        dt = torch.promote_types(x.dtype, n.dtype)
    else:
        dt = x.dtype
    if dt not in _FLOAT_DTYPES:
        raise ValueError(
            "special_chebyshev_polynomial_t only supports float32/float64, "
            f"but got {dt}"
        )

    out_shape = (
        torch.broadcast_shapes(x.shape, n.shape) if is_tensor_n else tuple(x.shape)
    )
    out = torch.empty(out_shape, dtype=dt, device=x.device)
    numel = out.numel()
    if numel == 0:
        return out

    is_fp64 = dt == torch.float64
    out_contig = tuple(x.shape) == tuple(out_shape) and x.is_contiguous()

    if not is_tensor_n:
        n_mode = 0
        n_val = float(n)
        poly_degree = (
            int(abs(n_val))
            if float(n_val).is_integer() and abs(n_val) <= _MAX_POLY_DEGREE
            else -1
        )
        flat = out_contig
    elif n.numel() == 1:
        n_mode = 1
        poly_degree = -1
        n_val = 0.0
        flat = out_contig
    else:
        n_mode = 2
        poly_degree = -1
        n_val = 0.0
        flat = out_contig and n.is_contiguous() and tuple(n.shape) == tuple(out_shape)

    grid = lambda meta: ((numel + meta["BLOCK"] - 1) // meta["BLOCK"],)
    if flat and poly_degree >= 0:
        _cheb_poly_kernel[grid](
            x,
            out,
            numel,
            DEGREE=poly_degree,
            IS_FP64=is_fp64,
        )
        return out
    if flat:
        _cheb_flat_kernel[grid](
            x,
            n if is_tensor_n else x,
            out,
            numel,
            n_val,
            N_MODE=n_mode,
            IS_FP64=is_fp64,
            MAXK=_MAX_INLINE_DEGREE,
        )
        return out

    ndim = len(out_shape)
    if ndim > _MAX_NDIM:
        raise NotImplementedError(
            "special_chebyshev_polynomial_t supports at most 5 broadcast dims"
        )
    xb = x.expand(out_shape)
    nb = n.expand(out_shape) if is_tensor_n else xb
    pad = _MAX_NDIM - ndim
    dims = (1,) * pad + tuple(out_shape)
    xs = (0,) * pad + tuple(xb.stride())
    ns = ((0,) * pad + tuple(nb.stride())) if is_tensor_n else (0,) * _MAX_NDIM
    _cheb_strided_kernel[grid](
        xb,
        nb,
        out,
        numel,
        n_val,
        xs[0],
        xs[1],
        xs[2],
        xs[3],
        xs[4],
        ns[0],
        ns[1],
        ns[2],
        ns[3],
        ns[4],
        dims[1],
        dims[2],
        dims[3],
        dims[4],
        N_MODE=n_mode,
        IS_FP64=is_fp64,
        BLOCK=_BLOCK,
        num_warps=_NUM_WARPS,
    )
    return out
